<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { exportarProgramaciones, obtenerDashboardCisternas } from '../services/dashboard'
import type { DashboardCisternasResponse } from '../interfaces/dashboard.interface'
const today=new Date(),first=new Date(today.getFullYear(),today.getMonth(),1),last=new Date(today.getFullYear(),today.getMonth()+1,0);const iso=(d:Date)=>{const offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,10)}
const filters=reactive({desde:iso(first),hasta:iso(last)}),data=ref<DashboardCisternasResponse|null>(null),loading=ref(false),exporting=ref(false),error=ref('')
async function load(){if(!filters.desde||!filters.hasta||filters.hasta<filters.desde){error.value='Seleccione un periodo válido.';return}loading.value=true;error.value='';try{data.value=await obtenerDashboardCisternas(filters.desde,filters.hasta)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function excel(){if(!filters.desde||!filters.hasta)return;exporting.value=true;try{await exportarProgramaciones(filters.desde,filters.hasta)}catch(e){error.value=message(e)}finally{exporting.value=false}}
const maxDay=computed(()=>Math.max(1,...(data.value?.series.por_dia.map(x=>x.total)??[]))),maxDistrict=computed(()=>Math.max(1,...(data.value?.series.por_distrito.map(x=>x.total)??[]))),maxReason=computed(()=>Math.max(1,...(data.value?.series.por_motivo.map(x=>x.total)??[]))),maxUnit=computed(()=>Math.max(1,...(data.value?.series.por_cisterna.map(x=>Math.max(x.viajes,x.m3))??[])))
const volumeDays=computed(()=>{const programmed=new Map((data.value?.series.capacidad_por_dia??[]).map(x=>[x.fecha,Number(x.m3??0)])),executed=new Map((data.value?.series.capacidad_real_por_dia??[]).map(x=>[x.fecha,Number(x.m3??0)]));return Array.from(new Set([...programmed.keys(),...executed.keys()])).sort().map(fecha=>({fecha,programado:programmed.get(fecha)??0,ejecutado:executed.get(fecha)??0}))}),maxVolume=computed(()=>Math.max(1,...volumeDays.value.flatMap(x=>[x.programado,x.ejecutado])))
const fmt=(value:number)=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:1}).format(value),date=(value:string)=>new Date(`${value}T00:00:00`).toLocaleDateString('es-PE',{day:'2-digit',month:'short'}),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo cargar el dashboard.'
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Gestión de Cisternas / Dashboard</nav><header class="hero"><div class="mark">DB</div><div><small>DANA · GESTIÓN DE CISTERNAS</small><h1>Dashboard de programaciones</h1><p>Indicadores de participación, viajes y volumen distribuido por las unidades.</p></div><button :disabled="exporting" @click="excel">{{exporting?'Generando…':'Exportar Excel'}}</button></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load"><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button :disabled="loading">{{loading?'Actualizando…':'Aplicar filtros'}}</button><small>* Volumen = capacidad de la cisterna × viajes.</small></form><div v-if="loading&&!data" class="empty">Calculando indicadores…</div><template v-else-if="data"><section class="kpis"><article><small>CISTERNAS ACTIVAS</small><b>{{fmt(data.kpis.total_cisternas)}}</b></article><article><small>PARTICIPACIONES</small><b>{{fmt(data.kpis.participaciones)}}</b><span>{{fmt(data.kpis.porcentaje_parti)}}% de la flota</span></article><article><small>PROGRAMACIONES</small><b>{{fmt(data.kpis.programaciones)}}</b></article><article><small>VIAJES EJECUTADOS</small><b>{{fmt(data.kpis.viajes_totales)}}</b></article><article><small>M³ PROGRAMADOS</small><b>{{fmt(data.kpis.m3_aproximados)}}</b></article><article><small>M³ EJECUTADOS</small><b>{{fmt(data.kpis.m3_ejecutados)}}</b></article><article class="progress"><small>CUMPLIMIENTO</small><b>{{fmt(data.kpis.porcentaje_cumpli)}}%</b><i><span :style="{width:`${Math.min(100,data.kpis.porcentaje_cumpli)}%`}"></span></i></article></section><section class="charts"><article class="wide"><header><div><small>EVOLUCIÓN DIARIA</small><h2>Volumen programado y ejecutado</h2></div><div class="legend"><span class="programmed">Programado</span><span class="executed">Ejecutado</span></div></header><div class="columns volume"><div v-for="row in volumeDays" :key="row.fecha"><section><i class="programmed" :style="{height:`${row.programado/maxVolume*100}%`}" :title="`${row.programado} m³`"></i><i class="executed" :style="{height:`${row.ejecutado/maxVolume*100}%`}" :title="`${row.ejecutado} m³`"></i></section><small>{{date(row.fecha)}}</small></div></div></article><article><header><div><small>PROGRAMACIONES</small><h2>Actividad por día</h2></div></header><div class="bars"><div v-for="row in data.series.por_dia" :key="row.fecha"><span>{{date(row.fecha)}}</span><i><b :style="{width:`${row.total/maxDay*100}%`}"></b></i><strong>{{row.total}}</strong></div></div></article><article><header><div><small>COBERTURA</small><h2>Distribución por distrito</h2></div></header><div class="bars"><div v-for="row in data.series.por_distrito" :key="row.distrito"><span>{{row.distrito}}</span><i><b :style="{width:`${row.total/maxDistrict*100}%`}"></b></i><strong>{{row.total}}</strong></div></div></article><article><header><div><small>FINALIDAD</small><h2>Programaciones por motivo</h2></div></header><div class="bars reasons"><div v-for="row in data.series.por_motivo" :key="row.motivo"><span>{{row.motivo}}</span><i><b :style="{width:`${row.total/maxReason*100}%`}"></b></i><strong>{{row.total}}</strong></div></div></article><article><header><div><small>PRODUCTIVIDAD</small><h2>Viajes y m³ por cisterna</h2></div></header><div class="bars units"><div v-for="row in data.series.por_cisterna" :key="row.id_cisterna"><span>{{row.cisterna}}</span><i><b :style="{width:`${row.m3/maxUnit*100}%`}"></b></i><strong>{{fmt(row.viajes)}} viajes · {{fmt(row.m3)}} m³</strong></div></div></article></section></template></div></template>
